ProjectALife.DialogueShards["radio_15"] = {
{"exp_new_neighbor","caller_story_sad",31,3650,0,23,1,{"Celia","I've learned someone's name without knowing their address","June","That must be different for a mail carrier","Celia","Before, I could picture a mailbox when someone introduced themselves","June","What do you picture now?","Celia","A person who offered to listen while I complained","June","That's a good introduction in any town","Celia","We argued about tomatoes for half an hour, nothing urgent at all","June","I'm glad you got half an hour back"}},
{"exp_pretty_mend","caller_story_sad",31,3650,0,23,1,{"Lottie","I repaired something neatly instead of just making it hold","June","What were you repairing?","Lottie","A cuff, took out the ugly stitches and did them again","June","Were the first ones loose?","Lottie","No, I just wanted it to look like a person cared","June","That doesn't sound wasteful to me","Lottie","Good, I was prepared to argue about it","June","You'll have to save that argument for a less agreeable host"}},
{"exp_joke_not_ready","caller_story_sad",31,3650,0,23,1,{"Tiny","Somebody made a joke yesterday and I got angry","June","Was it a cruel one?","Tiny","No, that's what made it worse, couldn't blame the joke","June","You weren't ready to laugh?","Tiny","Wasn't ready for everybody else to be ready","June","People don't arrive at the same moment together","Tiny","I know that now, didn't know it before I raised my voice","June","You can still tell them what you meant"}},
{"exp_tool_ownership","caller_joke",31,3650,0,23,1,{"Roy","Mack says putting my name on a tool is possessive","Mack","You put it on both sides","Roy","So it remains informative upside down","Mack","And the handle","Roy","That is another side people look at","Mack","What if your name wears off?","Roy","You'll still know it's mine, I'm telling the whole county now","June","Public records have taken a rather specific turn"}},
{"exp_remember_singing","music_bridge",31,3650,0,23,1,{"June","I'd like you to remember somebody singing badly","June","Not a famous singer, somebody you knew","June","Through a wall, at the wheel, while they washed a plate","June","You don't need to remember which song it was","June","Just the confidence of a person who didn't think they had an audience","June","My father was magnificent at not knowing the words","June","Never let that slow him down","June","I'm going quiet for a moment, you can give your person the room"}},
{"exp_bad_prediction","host",31,3650,0,23,1,{"June","I found a note I made early on, it said, ask someone how long this will last","June","Underlined someone, as though the right person was just busy","June","I don't keep that question on the desk anymore","June","Doesn't mean I've given up, means I'm trying to ask things somebody can answer","June","Did you eat? Did the repair hold? Did you hear from your friend?","June","Small questions aren't an insult to a big problem","June","Sometimes they're the only honest way into the afternoon","June","If you've got a small answer, there's room for it here"}},
{"exp_morning_routine","sign_on",31,3650,6,11,1,{"June","Morning, for those of you keeping the same hours I am","June","For everyone else, please accept a greeting without a time attached","June","I'm checking my notes before I start accepting calls","June","Most of them say things like speak slower and stop tapping the desk","June","There's no secret information hiding behind the sound of shuffled paper","June","Just me trying to be a little easier to listen to","June","If this reaches you clearly, that's one thing working today","June","Let's see if we can manage another without promising the whole world"}},
{"exp_new_holiday","caller_joke",31,3650,0,23,1,{"Russ","I'd like to propose a holiday","June","Does it require decorations we don't have?","Russ","No decorations, no gifts, nobody has to visit anybody","June","What exactly are we celebrating?","Russ","Not having to organize a holiday","June","That might interfere with your proposal","Russ","You're right, I'm canceling it in observance","June","A remarkably successful first year"}},
{"exp_mercenary_invoice","caller_joke",31,3650,0,23,1,{"Gray","I once spent six weeks arguing over reimbursement for a cab","June","Was it an expensive cab?","Gray","Less than the postage I used arguing","June","A matter of principle, then?","Gray","That's what you call losing money deliberately","June","Did you ever get reimbursed?","Gray","They paid half, I framed the letter","June","A certificate of partial victory"}},
{"more_radio_next_picnic","caller_joke",31,3650,0,23,1,{"Bess","I've started planning a picnic","June","A particular day?","Bess","No date yet - just... I'd like to eat outside without crouching behind something","June","What are you bringing?","Bess","Complaints about ants, I've missed those","Roy","I can complain about a folding chair","June","I'll sit on the ground, then, I've heard Roy with a folding chair","Lou","I'll bring a potato salad argument","Bess","No raisins, we're trying to rebuild civilization","Lou","Who's putting raisins in it? Bess, was that aimed at me?"}},
{"more_radio_new_handwriting","caller_story_sad",31,3650,0,23,1,{"Edith","I'm teaching a grown man to write his name","Edith","He asked me not to say which man","June","Then we won't ask","Edith","He can repair almost anything, kept telling me this ought to be easier","Edith","He grips the pencil so tight, keeps apologizing when the point breaks","Edith","Today he signed a note without copying mine","June","What did the note say?","Edith","'Thank you, Miss Edith.' All squashed into the corner, oh, I wish you could see it","June","You keeping it?","Edith","In my coat - keep checking it's there, I should really put it somewhere safer"}},
{"more_radio_good_coat","caller_story_sad",31,3650,0,23,1,{"Celia","I stopped saving a coat for a special occasion","June","Wearing it now?","Celia","Not right this second, but I've actually worn it - out in the mud","June","What were you saving it for?","Celia","A dinner - a visit, something where I'd look like I was doing well","Celia","It still had the paper in the pockets, little balls of tissue","June","How long had you had it?","Celia","Three years - maybe four - what the hell was I waiting for?","Celia","Got mud on the hem first time out, just wiped it off - wasn't even upset","June","Good for you, I hope it fits better than my good coat"}},
{"more_radio_engineer_garden","caller_joke",31,3650,0,23,1,{"Mack","Roy measured the garden rows with a string","Roy","Straight rows are easier to work","Mack","Then he measured the string","Roy","It had stretched","June","Mack, let him finish","Mack","That's what I'm waiting for! Nothing's even planted","Roy","We planted yesterday","Mack","After you checked whether the fence was square","June","What are you growing?","Roy","Beans, two rows of beans - he's made it sound like I'm building a goddamn airport"}},
{"more_radio_one_repaired_radio","caller_story_sad",31,3650,0,23,1,{"Carl","We fixed the little radio","June","The one you're listening on?","Carl","Yes, my daughter held a flashlight for an hour","June","An hour? That's a long time to hold a flashlight","Carl","No, complained the entire time, very good light, though","Carl","Kept asking if I was done - 'now? How about now?'","Carl","When your voice came through she looked at me like I'd done something enormous","Carl","Then she went, 'Dad! DAD, listen!' Right in my ear - as if I hadn't heard","Carl","I used to fix things every day, forgot it could feel like that","June","Tell your assistant we appreciate the light"}},
{"more_radio_mercenary_contract","caller_joke",31,3650,0,23,1,{"Gray","Someone offered to pay me after the banks reopened","Gray","Said his word was his bond","Caller","You take the job?","Gray","No, he said he'd double it - double WHAT? You can't pay the first half","Caller","That's a no, then","Gray","He tried to give me stock certificates","Caller","For what company?","Gray","Didn't ask, didn't want them - kept trying to put them in my hand","Caller","Should've asked for office furniture","Gray","A chair, maybe, been sitting on a crate, at least I'd use a chair"}},
{"knox_faded_photo","caller_story_sad",31,3650,0,23,1,{"Nora","My photograph got wet, half the faces have run together","June","Can you still tell who they are?","Nora","I can now. It's later I'm afraid of - when I won't have their faces to help me","June","Tell somebody the names, Nora. While you can still make them out"}},
{"knox_old_hands","host",31,3650,0,23,1,{"June","Some of you sound different now, not older exactly - less surprised","June","I can't decide if that's good, I suppose it gets us through the afternoon","June","If somebody new sounds frightened, try to remember your own first call","June","Nobody started this knowing what to do"}},
{"knox_card_game","caller_joke",31,3650,0,23,1,{"Art","Found forty-nine playing cards, been inventing rules","June","Any good ones?","Art","Yes, when I lose, it was one of the missing cards' fault","June","Sounds like you've invented a very old game"}},
{"knox_running_joke","caller_joke",31,3650,0,23,1,{"Cal","Remember how people paid to use a treadmill?","June","Yes, Cal","Cal","Running in one place - indoors, angry if somebody interrupted","June","I think we were all spoiled in very specific ways"}},
{"knox_goodnight_late","sign_off",31,3650,20,4,1,{"June","That's enough out of me for now","June","Thank you to the people who called, and the ones who only listened","June","You don't owe the microphone a brave voice, an ordinary one is fine","June","I hope we get to do this again"}},
{"r2_ghost_graduation_under_tape","military",31,54,19,3,2,{"Marty","The scanner still picks up the bridge, nobody has talked on that net in over a week - the tape is still running","Bridge Tape","Attention, this bridge is closed by order of the United States Army - turn around - turn around now","Bridge Tape","Stop, you are approaching an armed checkpoint - you will not, you will not be allowed to cross","Bridge Tape","This is your final warning, if you pass the burned car, you will be fired","Marty","Then there's a click, where the two ends of the loop are taped together - listen right past the click","Bridge Tape","From Muldraugh, Ashley Renee Dunn","Dee","That's the graduation underneath, the little piece he didn't record over, his sister's name comes around once every loop","Marty","I've been sitting here counting loops, I don't know what else to do with it - I'm glad something out there is still saying her name"}},
{"r2_ghost_net_call_one_present","military",31,90,5,7,1,{"Warden Tac","All stations, all stations, this is Warden Tac, morning net call - there is no Warden anymore, I'm calling it anyway, over","Warden Tac","Anvil, over - Hatchet, over - Crowbar, over","Warden Tac","Striker, over - Lockbox, over - Thoroughbred, over","Striker-12","Tac, Striker-12 - present, over","Warden Tac","Roger, Striker-12 - one present, same as yesterday - anything to report, over?","Striker-12","Negative, the fire channel says good morning, same time tomorrow, over","Warden Tac","Same time tomorrow - Warden Tac, out"}},
{"r2_ghost_dispatcher_hum","military_mistake",31,3650,21,3,1,{"Marty","There's an open carrier on the county road department channel tonight - nobody's talking, somebody left a handset keyed","Dee","Turn it up a hair - there - hear that?","Marty","A screen door, some wind chimes... and somebody humming, no words, just humming","Dee","Back in July an Army captain got on that channel and hollered at their dispatcher for humming - then he apologized and said she could hum all she wants","Marty","I remember, he said it on the air, so it counts","Dee","I'm going to let it play for a while, nobody call in over the top of it"}},
{"r2_ghost_relief_efforts_ongoing","military",31,3650,0,23,1,{"Outside Broadcast","This is a recorded message from the United States Army on behalf of the Commonwealth of Kentucky - the Knox County quarantine remains in effect","Outside Broadcast","Persons inside the quarantine line should remain in their homes - do not approach the perimeter, persons approaching the perimeter will be engaged","Outside Broadcast","Relief efforts are ongoing, further information will be broadcast on this frequency - this message will repeat","Marty","It does repeat, it has repeated every eleven minutes for as long as I've been able to find it - relief efforts are ongoing","Dee","Remain in your homes, I've asked around - nobody's home is where they left it","Marty","Further information will be broadcast, I'll let you know if it ever is - don't hold supper"}},
{"r2_ghost_signal_mirror","military",31,90,5,8,1,{"Dustoff 2-2","Any aircraft, any aircraft, Dustoff 2-2 on guard, survivor at the white barn with the red roof east of Rosewood, over","Dustoff 2-2","Any aircraft, Dustoff 2-2, some mornings I hear rotors - Panels are out on the grass, I have a signal mirror, over","Marty","That comes over at sunrise a few times a week, since before the Army quit - I have never once heard an aircraft answer him","Dee","If you live east of Rosewood and you know a white barn with a red roof, go look - carefully, he's been waiting on a helicopter, a pickup truck would do","Dustoff 2-2","Dustoff 2-2, will listen again at sunrise - out"}},
{"r2_ghost_bugle_at_five","military",31,3650,17,19,1,{"Marty","If you live near the post and the evening is still, you already know this - at five o'clock the loudspeakers at Fort Knox still play the bugle call for the end of the duty day","Marty","Nobody's there to lower the flag, it runs on a timer and somebody's generator - it has outlasted the Army that set it","Dee","Tonight the wind was right, so Marty stood out on the loading dock with the microphone cord stretched as far as it goes","Marty","It didn't carry, you got about forty seconds of crickets and me breathing - I'm told that isn't the same thing","Dee","It was a little the same"}},
{"r3_so_d31_leaning_cake","sign_on",31,33,5,8,4,{"Marty","Good morning, ninety-nine point six, it's {weekday}, {date}, and as of today we've been on the air one month","Marty","Somebody asked if we're doing anything to celebrate - Dee made a cake out of cornbread and a can of cherry pie filling - it's leaning","Dee","It is NOT leaning! Rustic, Marty, it's rustic","Marty","It's leaning, and it's the best thing I've eaten since July - here's what a month has taught this station, in one sentence - get up, look out before you go out, and count your people","Marty","It's {time}, scanner first, then the classifieds"}},
{"r3_sf_d31_shirt_pocket_matches","sign_off",31,60,22,23,1,{"Marty","That's the day... count your people, and know where your matches are without feeling around for them","Marty","We had a man on nineteen this week whose lamp went out while something rattled his back door, and he spent a full minute patting the kitchen counter","Marty","He's fine, he asked me to tell you the matches were in his shirt pocket the entire time","Marty","Good night from March Ridge"}},
{"r3_host_d31_classifieds","host",31,70,9,17,1,{"Marty","Time for the classifieds, which is what we call it now that Dee won't let me call it the market report","Dee","Because nothing is being marketed","Marty","A family on the Ekron road has a hand pump for a shallow well and needs a man who's put one in before - they'll feed you for the week it takes","Marty","Somebody's offering a working wind-up alarm clock for a pound of coffee - I'm told the clock is loud, I'm told that's the reason it's for sale","Marty","And the young fellow in Riverside who makes arrows out of dowel rods says he's sold out - I don't know what he got for them, I didn't ask","Marty","Leave your notes in the slot - print, we still can't read a lot of you"}},
{"r3_ins_d31_pressure_canner","instruction",31,75,6,12,1,{"Marty","Gardens are coming in, and some of you are canning for the first time in your life - Nancy canned, I carried jars, so I know just enough to scare you","Dee","I'll do the scaring - botulism, you can't see it, smell it, or taste it, and it'll stop you breathing","Dee","Green beans, corn, and meat need a pressure canner, a pot of boiling water doesn't get hot enough for those - tomatoes, pickles, and fruit, a water bath is fine - put a little vinegar or lemon juice in the tomatoes","Dee","If a lid's popped up, or bulging, or it spurts when you open it, bury it - don't taste it to check, nobody tastes to check","Marty","And if you're not sure about a jar of beans, don't eat it. Nancy would've hated wasting food, but she'd have hated losing you more"}},
{"r3_wx_d31_curled_corn","weather",31,50,5,10,1,{"Marty","Weather, no rain in eleven days, the corn in the fields nobody tended has curled up tight, which is how corn tells you it's thirsty","Marty","Ninety-five this afternoon, hot enough the blacktop goes soft on the Rosewood road - you'll see it shimmer out there, that isn't anything moving - probably","Marty","Wells are getting low, if yours starts coughing up sand or coming up cloudy, rest it a day and let it fill back in","Marty","Chance of a storm, according to my knee, somewhere between none and a little - my knee's drinking the same well water as the rest of us, so go easy on it"}},
{"r9_host_d32_tally_by_town","host",32,85,0,23,1,{"Marty","I keep a tally in the green ledger of every voice I hear, by town, one mark to a person - last night I added it up for the first time","Marty","March Ridge, thirty-one - Muldraugh, twenty-two - West Point, nineteen - Ekron, fourteen - Rosewood, nine - Riverside, four","Marty","Riverside is a bigger town than Ekron, I've got four","Dee","That could be radios, it could be the ridge, it could be a hundred things that aren't the bad thing","Marty","It could, I'm saying the number out loud because I've been carrying it around three days - Riverside, four, if you're over there and you can key up, key up - I don't need a conversation - say a name"}},
{"r9_sf_d33_lamp_in_the_window","sign_off",33,72,22,23,1,{"Marty","Going to shut her down, the gauge says I've got about four hours of talking left in the can, and I'd rather spend it in the morning than at eleven at night","Marty","A woman out on the Riverside road asked me tonight if it's foolish to keep a lamp in her front window - she knows exactly what a light in a window does - she asked me anyway","Marty","I told her I won't tell her to do it - and I told her if she does it, put the lamp in a back room and leave the front of that house dark, and keep the light for the people inside the house","Dee","That's a good answer, he worked on it for an hour and a half","Marty","I did, good night, all of you"}},
{"r9_ins_d34_gas_goes_stale","instruction",34,100,8,20,1,{"Marty","Somebody asked me how long the gas in a can will last. I can't see yours from here","Caller - Orval","Depends what it was stored in, Marty. I wouldn't give everybody one answer","Caller - Orval","Check the container and the vehicle before you blame the fuel. I've made that mistake","Marty","What about what's down in the tanks under a filling station?","Caller - Orval","I wouldn't tell anybody what's in a tank I haven't looked at. Nobody on this radio can do that for you","Caller - Orval","Use a proper fuel container and keep it marked. Don't leave somebody guessing what they're picking up","Marty","And don't siphon with your mouth - Orval, tell them why not","Caller - Orval","Because I did it in nineteen seventy-one and I was sick a week, and my wife has not let go of it since"}},
{"r2_ghost_farmhouse_toll","military",35,3650,0,23,1,{"Farmhouse","Any station, this is Farmhouse, we hold the county road between the co-op and Hollow Road now - toll is one can of food per person, per crossing","Farmhouse","Any soldier still stuck inside, the offer stands, we eat every day - go ask your colonel how often he eats, oh, that's right","Dee","That's the same man who invited soldiers out to his farm in July - he had a well then, now he has a toll","Marty","Hollow Road, the one a Guardsman spelled out in the police alphabet - stay off it, or bring two cans"}},
{"r3_sf_d35_thank_you_for_breathing","sign_off",35,70,0,2,1,{"Dee","It's late, and I'm tired, and I'm going to be honest, because it's two in the morning and nobody's honest at noon","Dee","Some nights I sit here and think I could just not key up - just sit, nobody would ever know","Dee","And then somebody on nineteen breathes into the mic before they say anything, the way you do when you're working up to it - and I key up","Dee","So thank you for breathing, off the air - good night"}},
{"r3_host_d35_shoes_and_hands","host",35,80,0,23,1,{"Marty","Something I've noticed, a month ago, when a stranger walked into this lot, I'd grab the hammer - now I look at their shoes first","Dee","Here we go, his shoes thing","Marty","Good shoes, clean hands: got a bed, wants to trade - bad shoes, clean hands: scared - dirty hands, hammer's close","Dee","And bare feet?","Marty","Bare feet means go get Dee","Dee","Bare feet means me, I'll go get my kit"}},
{"r3_mb_d35_spotter_cards","music_bridge",35,120,0,23,1,{"Marty","In place of music, I found a box of Lloyd's spotter cards from the football games - he kept the rosters on index cards, with little notes to himself","Marty","Number twenty-two, Dwayne Hatfield, sophomore, fast, fumbles in the rain - number fifty-four, big Tim Carrico, say his name right, his mother listens","Marty","Number eleven, the Moss boy, kicker, gets upset when he misses, don't mention it on the air","Marty","I won't read the rest, those boys would be seniors this fall, I'll just say, Tim Carrico, if you're out there, your mother would like to hear from you"}},
{"r9_so_d36_three_things_certain","sign_on",36,70,6,9,1,{"Marty","Good morning, it's {time} - here's the three things I know for certain, and then I'll quit talking like a man who knows things","Marty","One, the creek at the Ekron road bridge is down to rock - two, the Greers have hens laying again - three, nobody I've talked to has heard an airplane since the twenty-second","Marty","Everything else I say today is somebody telling me something they heard off somebody else - I'll tell you when it is, you keep track too, and hold it against me if I forget","Dee","Overnight was a cut hand, a woman who needed to talk till about two, and Marty snoring in the storeroom loud enough to come through the block wall","Marty","Ninety-nine point six - count your people"}},
{"r3_host_d37_hollis_wood","host",37,37,9,12,8,{"Reverend Hollis","Good morning, it's raining on this tin roof so loud I can barely hear myself, so if you can't hear me, that's alright - the rain's saying most of it","Reverend Hollis","I'll be short, this week a man came out to the church and asked if he could be forgiven for something he did in July - he wouldn't tell me what","Reverend Hollis","I told him I couldn't forgive anybody, that was never my job, he asked whose job it was - I said the people you did it to, and God, and the hardest one, yourself","Reverend Hollis","He said two of those three were gone, I told him that leaves one, and it's the one standing here, so he'd better get started","Reverend Hollis","He's been splitting wood for the fellowship hall every day since - I don't know if that's forgiveness, it's a lot of wood"}},
{"r3_so_d38_sevens_out_of_spite","sign_on",38,45,6,8,1,{"Marty","Good morning, it's {date}, in a regular year the school buses would be running this week - I used to hate getting stuck behind the one on the Rosewood road - it stopped at every mailbox","Marty","A lot of you with kids have asked about school - Dee's been teaching the children at the church their times tables in the afternoons, under protest","Dee","I'm a nurse, not a teacher, the seven-year-old is doing long division now purely out of spite","Marty","So if you've got kids, teach them something today - anything, how to tie a bowline, how to read a county map - the sevens","Marty","It's {time}, ninety-nine point six"}},
{"r9_joke_d38_best_fiddle_left","caller_joke",38,110,16,22,1,{"Caller - Vesta","Marty, you can tell the county that I am the best fiddle player left in it","Marty","That's a big thing to say out loud, Vesta","Caller - Vesta","Now, I'll be honest with you about the competition - Harlan Sipes was better than me and Harlan is gone - the Pruitt boy was better than both of us and nobody's heard from the Pruitt boy since July","Marty","So there's nobody left to argue","Caller - Vesta","There is nobody left to argue, which is exactly why I'm saying it now instead of waiting on somebody's permission","Caller - Vesta","And I'll play for anybody who comes to the porch - first one's free, second one, I'd like a tomato","Marty","Best fiddle player in Knox County, and the price is one tomato - I've heard worse deals out of this radio today"}},
{"r2_ghost_last_weather","military",40,70,5,8,1,{"Hatchet-7","All stations, Hatchet-7, weather for {date}, first cool morning since July - fifty-eight degrees down at the river, over","Hatchet-7","They move slower in the cool, do your walking early and get your water before nine, over","Hatchet-7","This is the last battery I have that holds a charge - I'm going to read one more thing and then go off the air, over","Hatchet-7","Hatchet company held the Dixie Highway starting the ninth of July - nobody ever told us when to stop, so I'm telling us - stop - Hatchet-7, out"}},
{"r3_host_d40_both_of_me","host",40,90,0,23,1,{"Dee","Personnel announcement, the feed store medical department has tripled in size","Dee","Kayla and Missy, sixteen and seventeen, trailed me three weeks - now they clean wounds and count a pulse without talking","Marty","The not talking was the hard part","Dee","The not talking was very hard, so if you come to the back door and a teenager takes your temperature, be nice - she's learning on you, and she will remember who was nice","Dee","I'm proud of them - no joke, only thing I've said all week that wasn't one"}},
{"r3_host_d40_waved_both_arms","host",40,150,0,23,1,{"Marty","A helicopter came over about two this afternoon, low, headed toward the river - a lot of you called in on nineteen about it","Marty","Same thing I told everybody who called: it didn't land, it didn't drop a thing, it didn't wave","Dee","Marty waved","Marty","I waved, I stood in the middle of the lot like a fool and waved both arms over my head, and I'd do it again tomorrow","Marty","What I'd tell you not to do is chase it - everything that heard it is walking the same way it flew - you'd be walking with them"}},
{"r3_ins_d40_rabbits_first_frost","instruction",40,110,0,23,1,{"Marty","Squirrel season would have opened this month, so a lot of you are out after them, and a lot of you are shooting","Marty","A .22 is quiet next to a shotgun, but it is not quiet - a snare is quiet, a box trap is quiet, you'll catch less, but you won't have company come to see what you caught","Dee","When you clean a rabbit, wear gloves if you've got them - rabbits carry a fever you can catch through a cut on your hand - if a rabbit's acting slow and stupid, let it go - something's wrong with it","Marty","The old men said don't eat rabbit till after the first frost - they were right about that more often than they were about the weather","Dee","And cook everything all the way through - everything, I'm not doing another round of what we went through in August"}},
{"r3_sil_d40_harlan_on_the_bin","silence",40,120,6,10,1,{"Marty","We were gone two days - here's why, the antenna mast worked loose in the wind, and I wasn't climbing a grain bin in the dark, and Dee wasn't letting me climb it in the daylight either","Dee","Harlan went up - Harlan's afraid of nothing but his wife","Marty","We're back, thank you to the nine of you who walked over to check - you brought four jars of pickles - we're rich"}},
{"r5_host_dee_sits_out","host",40,200,0,23,1,{"Marty","Dee is sitting this hour out, last week she talked a man through setting his boy's arm over the air, and it went fine","Marty","It was the fever afterward, she stayed on the radio with him through last night, to the end","Marty","She asked me to tell that man, if he's listening, that she doesn't mind he turned the radio off after - she'd have done the same","Marty","So, let's take a call - I'd like somebody with something ordinary for us, if you've got it"}},
{"r5_joke_dwayne_horseshoe_champion","caller_joke",40,300,17,22,1,{"Caller - Dwayne","This is Dwayne Rakes, and I'd like to announce that I remain the undefeated horseshoe champion of Echo Creek","Marty","Congratulations, Dwayne - who'd you beat?","Caller - Dwayne","Nobody, nobody showed up - eleven weeks running","Marty","Then how are you undefeated?","Caller - Dwayne","Marty, have I been defeated?","Marty","No, Dwayne","Caller - Dwayne","Tournament's this Saturday, behind the Echo Creek church, entry is one can of anything, I'm still the favorite"}},
{"r5_joke_mitch_vcr_clock","caller_joke",40,300,17,22,1,{"Caller - Mitch","Marty, I got a generator running for the first time this week","Marty","That's good news, Mitch","Caller - Mitch","First thing that happened, the VCR came on and started blinking twelve o'clock","Caller - Mitch","World's over, and that VCR still wants somebody to set the clock - nine years I never did it, nine years it never gave up on me","Caller - Mitch","So I set it, took forty minutes and the manual - most useful thing I've done all month"}},
{"r5_joke_cheryl_apple_butter","caller_joke",40,300,17,22,1,{"Caller - Cheryl","I have a confession for the whole county","Dee","Go ahead, Cheryl, we don't judge","Caller - Cheryl","I was clearing a cellar out past Fallas Lake and found a jar of apple butter - the lid says 'Mamaw, fall of ninety-one'","Caller - Cheryl","I sat down right there on that dirt floor and ate half of it with my fingers","Dee","Cheryl, that's not much of a confession","Caller - Cheryl","It wasn't my mamaw, Dee, it was somebody else's mamaw, and it was so good, thank you, somebody's mamaw"}},
{"r7_mil_ghost_route_brief_tape","military",40,150,0,23,1,{"Roadmaster-3","Serial one, this is your route brief, start point the armory, release point the Muldraugh gate - speed forty, interval fifty meters","Roadmaster-3","Halt at the top of each hour, water at the co-op lot, fuel at the co-op lot - do not use the interstate","Roadmaster-3","Critical point is the Salt River bridge, one lane northbound - Kentucky State Police at the south end","Roadmaster-3","Serial one, acknowledge, over","Roadmaster-3","Serial one, this is your route brief, start point the armory, release point the Muldraugh gate - speed forty, interval fifty meters","Roadmaster-3","Halt at the top of each hour, water at the co-op lot, fuel at the co-op lot - do not use the interstate"}},
{"r9_trade_d42_nobody_showed","trade",42,105,9,16,1,{"Marty","A trade went bad Thursday, and I'd rather stand here and say it out loud than have it whispered up and down this county for a week","Marty","A man drove eleven miles to the Rosewood courthouse steps with five gallons of gas to swap for medicine - nobody came, he stood out there an hour and a half in the open with five gallons of gas in the truck bed","Marty","Nothing happened to him, I want that clear - but something could have, and it would have been partly mine","Dee","And the one who didn't show might have had a reason, might be dead, that's how it is now, not always somebody sorry","Marty","So, Trading Post rules, and these are permanent - daylight, out in the open where you can see three ways - two to a side, if your party isn't there in twenty minutes, you leave, and you don't feel one bit bad about leaving","Marty","And if you can't make it, get word to me any way you can and I'll say so on the air - nobody's mad at you, we're just done standing in parking lots"}},
{"r3_host_d44_hollis_third_ribbon","host",44,44,9,12,8,{"Reverend Hollis","Good morning, this would be State Fair week up in Louisville, I went every year for sixty years, missed it in forty-four - I was in the Pacific","Reverend Hollis","My wife and I used to go look at the quilts - she entered one every year, and she got the white ribbon, third place, eleven years running","Reverend Hollis","She said third was the best place to be, because first has to live up to it, and second is mad","Reverend Hollis","I've been thinking that's not bad advice for now - don't try to be first at anything - don't be mad about second - get a ribbon","Reverend Hollis","That's all I've got - Marty, is there any of that cornbread left?","Marty","No sir"}},
{"r9_host_d44_dee_hands","host",44,105,0,23,1,{"Marty","Dee - hold up your hands, I know they can't see them - describe your hands","Dee","Split at every knuckle, and I can't feel the tips of two fingers on the left one - that's lye soap and hot water forty times a day, and nothing else","Dee","I'm telling you because about half of you are doing the same thing to yourselves and calling it being careful - wash, yes, but get some grease on them at night - lard, bag balm, petroleum jelly, whatever's in the house","Dee","A split knuckle is a door, I have watched a man lose an arm through a door about that wide","Marty","She sat up last night rubbing lard into her own hands and grading my solder joint at the same time","Dee","The joint's fine, his hands are worse than mine and he washes them about twice a week"}},
{"r2_ghost_hammer_answers","military",45,3650,0,4,2,{"Hammer-3-1","Hammer-3-7, Hammer-3-7, this is Hammer-3-1, radio check, over","Hammer-3-1","Hammer-3-7, Hammer-3-1, we heard you calling - say again your last, over","Marty","That came in around two this morning on the old Army frequency - some of you remember a sergeant calling Hammer-3-1 every hour, back in July","Dee","Those nine were found, their tags came back tied up in a sock - we heard that too","Marty","So I don't know who that is, somebody found their radio at the water plant, most likely - somebody who has been listening for a long time","Hammer-3-1","Hammer-3-7, Hammer-3-1, we're still at the plant - come get us, over","Dee","Nobody go to that water plant... whoever wants you there has had a month to practice asking"}},
{"r3_so_d45_tobacco_in_flower","sign_on",45,60,5,7,1,{"Marty","Morning - it's {time}, this time of year, if you drove the back roads, you'd see tobacco cut and speared on sticks in the fields, drying before it went up in the barns","Marty","Nobody cut it this year, it's standing out there gone to flower, pink and white, clear to the tree line - I've never seen that in my life, it's pretty, and I hate it","Marty","The barns are empty, and some of you are sleeping in them - a tobacco barn has good air and a lot of ways out - it also has a lot of ways in - think about both","Marty","Ninety-nine point six - good morning - count your people"}},
{"r3_host_d45_noon_checkin","host",45,110,11,13,1,{"Marty","Noon check-in, if you're a regular on nineteen, key up and give me your place, your number, and how you're doing - keep it short","Caller - Harold","Colburn, this is Harold, on the Ekron road, nine of us, hand pump's working, lost a goat to something with teeth, don't know which kind","Marty","Copy, Harold, nine and a pump, sorry about the goat","Caller - Joyce","Joyce, at the grain elevator in Riverside - six, somebody's been in our garden at night taking only the tomatoes - whoever you are, you've got good taste, and I've got a shotgun","Marty","Copy, Joyce, six and a shotgun, tomato thief, you've been told","Caller - Luis","This is Luis, in West Point, four of us - we came in off the river - we're alright, we need a size eight shoe for a woman - that's all","Marty","Copy, Luis, four, and a size eight, I believe there's one on the wall - anybody else? No? That's twenty-three people I can put a number on this hour - good check-in"}},
{"r3_ins_d45_mailbox_colors","instruction",45,120,0,23,1,{"Marty","Back in July I asked you to tie something white on your mailboxes - some of you left them up, faded out gray by now, and people have started reading them as meaning something","Marty","So let's agree, white on the mailbox, people live here and they'll talk to you in daylight - red, somebody's sick inside - keep walking, and leave something on the post if you can spare it","Marty","Nothing on the mailbox means nothing - don't read a bare mailbox as an empty house, some folks just don't want company","Marty","And if a white rag's been taken down, where it used to be up, that's worth noticing - maybe they moved on, maybe holler from the road before you go knocking"}},
{"r3_mb_d45_tin_roof_rain","music_bridge",45,150,0,23,1,{"Marty","It's raining on the tin roof over the back office, and I'll be honest, it sounds better than anything I could put on - I'm going to hush a minute and let you have it","99.6 FM","(Rain on a tin roof, steady, for a while, a drip somewhere keeps landing in a pan)","Marty","That drip is the corner of the roof the Riverside family didn't get to - it keeps good time, so I'm leaving it"}},
{"r3_sil_d45_one_shot_far_off","silence",45,150,13,18,1,{"Marty","We're going to go quiet a few minutes, there's a crowd of them on the road out front, a big one, headed east - we'd like them to keep headed east","99.6 FM","(A long silence, once, a long way off, a single shot)"}},
{"r5_host_stitches_pigskin_gloves","host",45,150,0,23,1,{"Dee","Tonight I taught Marty how to put in a stitch, in case it's ever me that needs one","Marty","We practiced on a pair of pigskin work gloves off the rack by my register - nine ninety-five, retail","Dee","His first stitch looked like a barbed wire fence after a tornado went through it","Marty","The glove didn't complain","Dee","By the twentieth he was decent, I'd let him do my leg, I would not let him near my face","Marty","Nobody is letting me near a face, that's a promise to the whole county"}},
{"r9_ins_d47_hand_pump","instruction",47,130,8,20,1,{"Marty","For everybody on a well with no power, which is about all of us - this is the long answer, so go get a pencil and I'll wait","Caller - Ruel","It's Ruel, out past the Greers, if you've got an old dug well with a big casing you can drop a bucket on a rope - most wells around here aren't that, most are four inch or six inch pipe","Caller - Ruel","In a four inch you want a well bucket, which is a long skinny thing with a valve in the bottom of it - a man can build one out of pipe, a marble and a washer - I have built two","Marty","And a hand pump?","Caller - Ruel","A pitcher pump will only pull water up about twenty-five feet - if your water sits deeper than that it will not lift it, and cussing don't change it - deeper than that you need a deep well pump, and they are getting scarce","Caller - Ruel","Prime it with water you saved back, not with the last water in the house - keep a jug beside the pump, call it the pump's jug, and nobody drinks out of the pump's jug","Dee","And whatever comes up out of the ground, boil it - a pump doesn't clean anything, all a pump does is move it","Marty","The pump's jug, that's a good rule, Ruel, folks, go write that on the jug"}},
{"r9_sil_d49_crickets_counted","silence",49,120,20,23,1,{"Marty","I'm going to hold this microphone out the back window a minute - there's nothing wrong, just listen to what's out there","Marty","All right, you count the chirps in fourteen seconds and add forty and that's about the temperature - my grandad taught me that and it has never once been off by more than two","Marty","I got seventy-eight, that's warmer than the bin says - I'm going with the crickets","Dee","He is not going with the crickets, he wrote down the bin","Marty","I wrote down both"}},
{"r3_sf_d50_four_day_boot","sign_off",50,90,22,23,1,{"Marty","Night, all - count your people, and get those boots out of the wet","Marty","Dee showed me a foot this week that I won't describe, except to say it had been inside a wet boot for four days, and it belonged to a grown man who should've known better","Dee","He knows better now","Marty","Ninety-nine point six, off the air"}},
{"r3_host_d50_guardsman_message","host",50,90,9,20,1,{"Marty","I've been asked to pass something along from a fellow who was National Guard and still wears most of the uniform - he'd have said it himself, but his radio's dead","Marty","He says some Guard and a few regulars are holding a place north of here - won't say where, and they're not the cordon","Marty","He says they'll trade medical supplies for fuel, and they won't shoot a man whose hands are empty and up - his words, not mine","Marty","I'm reading it the way he gave it to me - I don't know him - Dee stitched his hand and he didn't cry, which is all the reference I've got","Dee","He cried a little","Marty","He cried a little - take it for what it is"}},
{"r5_trade_honey_amos","trade",50,200,9,16,1,{"Caller - Amos","Marty, I keep bees out on Echo Creek Road - eleven hives, I pulled more honey this year than any year since I started","Marty","What are you looking for, Amos?","Caller - Amos","Canning lids and rings, a bee veil, if anybody has one, mine's more hole than veil, I'll do two jars of honey for a dozen lids","Dee","I'll add something - clean raw honey on a scrape can help keep it from festering - wash the wound first, it's not a miracle","Dee","And no honey at all for babies under a year - not even a dab on a pacifier","Caller - Amos","Echo Creek Church of Christ, the parking lot, three in the afternoon","Marty","Echo Creek Church of Christ, three PM, two jars for a dozen lids - bring your own sting kit"}},
{"r5_trade_rita_puppies_basket","trade",50,250,9,16,1,{"Caller - Rita","I've got five puppies, eight weeks old, mama's a blue heeler - Daddy is anybody's guess","Marty","What are you asking, Rita?","Caller - Rita","A good home, and I've been training them quiet, when one yips, it gets picked up and held till it hushes - works on the smart ones","Dee","Wendell is shaking his head, everybody, he does not want help around here","Caller - Rita","I'll take dog food if anybody's got it, if not, just take a puppy","Caller - Rita","The West Point town hall steps, noon, they'll be in a laundry basket","Marty","Five puppies in a laundry basket, West Point town hall, noon - Wendell, you're still the only employee"}},
{"r7_mil_ghost_authenticate_forever","military",50,200,0,23,1,{"TCP 5","Station calling, this is TCP 5, authenticate Whiskey Delta, over","TCP 5","Station calling, TCP 5, authenticate Whiskey Delta, over","TCP 5","Nothing heard - TCP 5 remains at the barrier, over","TCP 5","Station calling, this is TCP 5, authenticate Whiskey Delta, over","TCP 5","I have been calling this out every hour since the fourteenth - I'd take a wrong answer at this point, just say something, over","TCP 5","Nothing heard - TCP 5, out"}},
{"r3_host_d51_hollis_empty_drawer","host",51,51,9,12,8,{"Reverend Hollis","I want to confess something on the radio, which isn't how we do it in my church, but this is the pulpit I've got","Reverend Hollis","Wednesday I sat on the parsonage steps for an hour and couldn't make myself walk over to the fellowship hall - fourteen people waiting on me to say something about a little boy we lost","Reverend Hollis","I didn't have a thing, forty years of it, and the drawer was empty","Reverend Hollis","Ada Ogle came out and stood over me and said, 'Walter, nobody needs you to talk - they need you in the room.' So I went and was in the room","Reverend Hollis","If your drawer's empty this week, go be in the room anyway - I learned that from a piano teacher"}},
}
